namespace OpenClaw.SetupEngine.Tests;

public sealed class LocalAiHardwareProbeCacheTests
{
    [Fact]
    public async Task DiskShortageIsReprobedWhenSetupIsRevisited()
    {
        const long gib = 1024L * 1024 * 1024;
        var lowDisk = new HostHardwareInfo(Architecture.X64, 32 * gib, 24 * gib,
            [new(GpuVendor.Nvidia, "Synthetic 8 GiB GPU", 8 * gib, 8 * gib,
                CudaMajorVersion: 13, StableId: "fixture-gpu")], false, new(4 * gib, 4 * gib, true));
        var calls = 0;
        var cache = new LocalAiHardwareProbeCache(() => Interlocked.Increment(ref calls) == 1
            ? lowDisk : lowDisk with { LocalAiDiskSpace = new(16 * gib, 16 * gib, true) });
        Assert.False(LocalInferenceEligibility.Evaluate(await cache.GetAsync()).CanInstall);
        Assert.True(LocalInferenceEligibility.Evaluate(await cache.GetAsync()).CanInstall);
        Assert.Equal(2, calls);
    }

    private static readonly HostHardwareInfo Complete = new(Architecture.X64, 128L << 30, 96L << 30,
        [new(GpuVendor.Nvidia, "Synthetic GPU", 48L << 30, 44L << 30,
            DriverVersion: "999.0", CudaMajorVersion: 13, StableId: "fixture-gpu")], false);

    [Fact]
    public async Task IncompleteFactsAreReprobedWithoutAnExplicitRefreshThenCompleteFactsAreReused()
    {
        var incomplete = new HostHardwareInfo(Architecture.X64, null, null,
            [new(GpuVendor.Nvidia, "Synthetic incomplete GPU")], false);
        Assert.Equal(LocalInferenceEligibilityFailureCode.HardwareFactsIncomplete,
            LocalInferenceEligibility.Evaluate(incomplete).FailureCode);
        var calls = 0;
        var cache = new LocalAiHardwareProbeCache(() =>
            Interlocked.Increment(ref calls) == 1 ? incomplete : Complete);
        var first = cache.GetAsync();
        Assert.Same(incomplete, await first);
        var retry = cache.GetAsync();
        Assert.NotSame(first, retry);
        Assert.Same(Complete, await retry);
        Assert.Same(retry, cache.GetAsync());
        Assert.Equal(2, calls);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task FaultedOrCancelledProbeDoesNotPoisonTheWindowCache(bool cancelled)
    {
        var calls = 0;
        var cache = new LocalAiHardwareProbeCache(() =>
        {
            if (Interlocked.Increment(ref calls) > 1) return Complete;
            if (cancelled) throw new OperationCanceledException();
            throw new InvalidOperationException("Synthetic probe failure");
        });
        if (cancelled) await Assert.ThrowsAnyAsync<OperationCanceledException>(() => cache.GetAsync());
        else await Assert.ThrowsAsync<InvalidOperationException>(() => cache.GetAsync());
        Assert.Same(Complete, await cache.GetAsync());
        Assert.Equal(2, calls);
    }

    [Fact]
    public async Task PendingProbeIsSharedAndExplicitRefreshCreatesANewProbe()
    {
        var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        using var release = new ManualResetEventSlim();
        var calls = 0;
        var cache = new LocalAiHardwareProbeCache(() =>
        {
            Interlocked.Increment(ref calls);
            entered.TrySetResult();
            if (!release.Wait(TimeSpan.FromSeconds(30)))
                throw new TimeoutException("The test probe was not released.");
            return Complete;
        });
        var first = cache.GetAsync();
        try
        {
            await entered.Task.WaitAsync(TimeSpan.FromSeconds(10));
            Assert.Same(first, cache.GetAsync());
            Assert.Equal(1, calls);
        }
        finally
        {
            release.Set();
            await first.WaitAsync(TimeSpan.FromSeconds(10));
        }
        var refreshed = cache.GetAsync(forceRefresh: true);
        Assert.NotSame(first, refreshed);
        Assert.Same(Complete, await refreshed);
        Assert.Equal(2, calls);
    }
}

namespace OpenClaw.SetupEngine.Tests;

public class RetryExecutorTests
{
    private SetupLogger CreateLogger() => new(filePath: null, LogLevel.Trace);

    [Fact]
    public async Task ExecuteWithRetry_SuccessOnFirstAttempt_ReturnsSuccess()
    {
        using var logger = CreateLogger();
        var result = await RetryExecutor.ExecuteWithRetry(
            () => Task.FromResult(StepResult.Ok("done")),
            RetryPolicy.Default,
            logger, "test-step", CancellationToken.None);

        Assert.Equal(StepOutcome.Success, result.Outcome);
        Assert.Equal("done", result.Message);
    }

    [Fact]
    public async Task ExecuteWithRetry_FailsThenSucceeds_RetriesAndReturnsSuccess()
    {
        using var logger = CreateLogger();
        int attempts = 0;

        var result = await RetryExecutor.ExecuteWithRetry(
            () =>
            {
                attempts++;
                return Task.FromResult(attempts < 3
                    ? StepResult.Fail("not yet")
                    : StepResult.Ok("success on 3rd"));
            },
            new RetryPolicy(MaxAttempts: 3, InitialDelay: TimeSpan.FromMilliseconds(1)),
            logger, "test-step", CancellationToken.None);

        Assert.Equal(3, attempts);
        Assert.Equal(StepOutcome.Success, result.Outcome);
    }

    [Fact]
    public async Task ExecuteWithRetry_AllAttemptsFail_ReturnsLastFailure()
    {
        using var logger = CreateLogger();
        int attempts = 0;

        var result = await RetryExecutor.ExecuteWithRetry(
            () =>
            {
                attempts++;
                return Task.FromResult(StepResult.Fail($"fail #{attempts}"));
            },
            new RetryPolicy(MaxAttempts: 3, InitialDelay: TimeSpan.FromMilliseconds(1)),
            logger, "test-step", CancellationToken.None);

        Assert.Equal(3, attempts);
        Assert.Equal(StepOutcome.Failed, result.Outcome);
        Assert.Equal("fail #3", result.Message);
    }

    [Fact]
    public async Task ExecuteWithRetry_TerminalFailure_StopsRetrying()
    {
        using var logger = CreateLogger();
        int attempts = 0;

        var result = await RetryExecutor.ExecuteWithRetry(
            () =>
            {
                attempts++;
                return Task.FromResult(StepResult.Terminal("unrecoverable"));
            },
            new RetryPolicy(MaxAttempts: 5, InitialDelay: TimeSpan.FromMilliseconds(1)),
            logger, "test-step", CancellationToken.None);

        Assert.Equal(1, attempts);
        Assert.Equal(StepOutcome.FailedTerminal, result.Outcome);
    }

    [Fact]
    public async Task ExecuteWithRetry_ExceptionInAction_CatchesAndRetries()
    {
        using var logger = CreateLogger();
        int attempts = 0;

        var result = await RetryExecutor.ExecuteWithRetry(
            () =>
            {
                attempts++;
                if (attempts < 3)
                    throw new InvalidOperationException("boom");
                return Task.FromResult(StepResult.Ok("recovered"));
            },
            new RetryPolicy(MaxAttempts: 3, InitialDelay: TimeSpan.FromMilliseconds(1)),
            logger, "test-step", CancellationToken.None);

        Assert.Equal(3, attempts);
        Assert.Equal(StepOutcome.Success, result.Outcome);
    }

    [Fact]
    public async Task ExecuteWithRetry_ExceptionExhaustsRetries_ReturnsFailWithExceptionMessage()
    {
        using var logger = CreateLogger();

        var result = await RetryExecutor.ExecuteWithRetry(
            () => throw new InvalidOperationException("always fails"),
            new RetryPolicy(MaxAttempts: 2, InitialDelay: TimeSpan.FromMilliseconds(1)),
            logger, "test-step", CancellationToken.None);

        Assert.Equal(StepOutcome.Failed, result.Outcome);
        Assert.Contains("always fails", result.Message);
    }

    [Fact]
    public async Task ExecuteWithRetry_CancellationBeforeStart_ThrowsOCE()
    {
        using var logger = CreateLogger();
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAsync<OperationCanceledException>(() =>
            RetryExecutor.ExecuteWithRetry(
                () => Task.FromResult(StepResult.Ok()),
                RetryPolicy.Default,
                logger, "test-step", cts.Token));
    }

    [Fact]
    public async Task ExecuteWithRetry_CancellationDuringAction_PropagatesCancellation()
    {
        using var logger = CreateLogger();
        using var cts = new CancellationTokenSource();

        await Assert.ThrowsAsync<OperationCanceledException>(() =>
            RetryExecutor.ExecuteWithRetry(
                () =>
                {
                    cts.Cancel();
                    cts.Token.ThrowIfCancellationRequested();
                    return Task.FromResult(StepResult.Ok());
                },
                new RetryPolicy(MaxAttempts: 3, InitialDelay: TimeSpan.FromMilliseconds(1)),
                logger, "test-step", cts.Token));
    }

    [Fact]
    public async Task ExecuteWithRetry_NoRetryPolicy_RunsOnce()
    {
        using var logger = CreateLogger();
        int attempts = 0;

        var result = await RetryExecutor.ExecuteWithRetry(
            () =>
            {
                attempts++;
                return Task.FromResult(StepResult.Fail("no retry"));
            },
            RetryPolicy.None,
            logger, "test-step", CancellationToken.None);

        Assert.Equal(1, attempts);
        Assert.Equal(StepOutcome.Failed, result.Outcome);
    }

    [Fact]
    public void RetryPolicy_Default_Has3Attempts()
    {
        Assert.Equal(3, RetryPolicy.Default.MaxAttempts);
    }

    [Fact]
    public void RetryPolicy_None_Has1Attempt()
    {
        Assert.Equal(1, RetryPolicy.None.MaxAttempts);
    }
}

using System;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;

namespace OpenClaw.TestSupport;

/// <summary>
/// Tiny JSON-RPC over HTTP client for the MCP endpoint. Exposes the two methods
/// these tests need (tools/list, tools/call) plus a generic Send for anything
/// else. Each call is a fresh POST — the MCP HTTP transport is request/response,
/// not session-based.
/// </summary>
public sealed class McpClient : IDisposable
{
    private readonly HttpClient _http;
    private readonly string _endpoint;
    private int _id;

    public McpClient(string endpoint) : this(endpoint, authToken: null) { }

    public McpClient(string endpoint, string? authToken)
    {
        _endpoint = endpoint;
        _http = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        if (!string.IsNullOrEmpty(authToken))
        {
            _http.DefaultRequestHeaders.Authorization =
                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", authToken);
        }
    }

    public Task<JsonDocument> InitializeAsync()
        => SendAsync("initialize", parameters: null);

    public Task<JsonDocument> ListToolsAsync()
        => SendAsync("tools/list", parameters: null);

    /// <summary>
    /// Call a tool. Returns the parsed JSON-RPC response. Caller checks
    /// result.isError and result.content[0].text per MCP spec.
    /// </summary>
    public Task<JsonDocument> CallToolAsync(string name, object? arguments = null)
    {
        var parameters = arguments is null
            ? (object)new { name }
            : new { name, arguments };
        return SendAsync("tools/call", parameters);
    }

    public async Task<JsonDocument> SendAsync(string method, object? parameters)
    {
        var id = System.Threading.Interlocked.Increment(ref _id);
        var requestObj = parameters is null
            ? (object)new { jsonrpc = "2.0", id, method }
            : new { jsonrpc = "2.0", id, method, @params = parameters };
        var requestJson = JsonSerializer.Serialize(requestObj);

        using var content = new StringContent(requestJson, Encoding.UTF8, "application/json");
        using var resp = await _http.PostAsync(_endpoint, content).ConfigureAwait(false);
        var body = await resp.Content.ReadAsStringAsync().ConfigureAwait(false);

        if (!resp.IsSuccessStatusCode)
        {
            throw new HttpRequestException(
                $"MCP HTTP {(int)resp.StatusCode}: {body}");
        }

        return JsonDocument.Parse(body);
    }

    /// <summary>
    /// Convenience: call a tool, assert the JSON-RPC envelope is well-formed,
    /// and return result.content[0].text parsed as JSON. Throws if the tool
    /// returned isError=true.
    /// </summary>
    public async Task<JsonDocument> CallToolExpectSuccessAsync(string name, object? arguments = null)
    {
        using var doc = await CallToolAsync(name, arguments).ConfigureAwait(false);
        var result = doc.RootElement.GetProperty("result");
        var isError = result.GetProperty("isError").GetBoolean();
        var text = result.GetProperty("content")[0].GetProperty("text").GetString();
        if (isError)
        {
            throw new InvalidOperationException($"Tool {name} returned isError=true: {text}");
        }
        return JsonDocument.Parse(text!);
    }

    /// <summary>
    /// Call a tool and return a tuple of (isError, payloadText). Use when the
    /// test should accept either success or a tool error (e.g. hardware-gated
    /// commands like canvas.eval without an active canvas window).
    /// </summary>
    public async Task<(bool IsError, string Text)> CallToolAcceptingFailureAsync(string name, object? arguments = null)
    {
        using var doc = await CallToolAsync(name, arguments).ConfigureAwait(false);
        var result = doc.RootElement.GetProperty("result");
        var isError = result.GetProperty("isError").GetBoolean();
        var text = result.GetProperty("content")[0].GetProperty("text").GetString() ?? "";
        return (isError, text);
    }

    public void Dispose() => _http.Dispose();
}

